"""Actual image writer with generated bytes and an in-process synthetic client."""
import io
import socket
from types import SimpleNamespace

import pytest
from PIL import Image

from pixivvault_nicegui import managed_downloads as downloads
from pixivvault_nicegui.bookmark_remote_adapter import RemoteBookmark
from pixivvault_nicegui.job_service import JobService


@pytest.fixture(autouse=True)
def no_network(monkeypatch):
    def reject(*args, **kwargs):
        raise AssertionError("no network permitted")
    monkeypatch.setattr(socket.socket, "connect", reject)
    monkeypatch.setattr(socket, "create_connection", reject)
    monkeypatch.setattr(socket, "getaddrinfo", reject)


def image_bytes(fmt="PNG"):
    out = io.BytesIO()
    Image.new("RGB", (2, 2), (20, 30, 40)).save(out, format=fmt)
    return out.getvalue()


class SyntheticClient:
    def __init__(self, data):
        self.data = data
        self.calls = 0

    def verify_identity(self):
        self.calls += 1

    def get_artwork_original_pages(self, work_id):
        return ("synthetic-original",)

    def get_image_bytes(self, url):
        return self.data


def make_writer(tmp_path, data):
    record = RemoteBookmark("1", "illustration", "show", "synthetic",
                            "2", "synthetic author", (), "", "", 1, 0, 0)
    client = SyntheticClient(data)
    writer = downloads.ManagedPixivDownloads(
        tmp_path / "generated-root", client, resolve_record=lambda _: record)
    return writer, client


def wait_terminal(service):
    with service._condition:
        assert service._condition.wait_for(
            lambda: service.snapshot() and service.snapshot()[0].state in {"error", "done"},
            timeout=3)
    return service.snapshot()[0]


@pytest.mark.parametrize("case,code,phrase", [
    ("corrupt", "image_format_invalid", "画像形式"),
    ("empty", "image_format_invalid", "画像形式"),
    ("unsupported", "image_format_invalid", "画像形式"),
    ("bytes", "image_size_limit", "画像サイズ"),
    ("pixels", "image_size_limit", "画像サイズ"),
    ("bomb", "image_size_limit", "画像サイズ"),
    ("total", "download_size_limit", "合計サイズ"),
])
def test_actual_image_failure_persists_and_displays(tmp_path, monkeypatch, case, code, phrase):
    data = image_bytes()
    if case == "corrupt":
        data = b"synthetic-cookie=private; token=private; S:/private/file.png"
    elif case == "empty":
        data = b""
    elif case == "unsupported":
        data = image_bytes("GIF")
    elif case == "bytes":
        monkeypatch.setattr(downloads, "MAX_PAGE_BYTES", len(data) - 1)
    elif case == "pixels":
        monkeypatch.setattr(downloads, "MAX_PIXELS", 3)
    elif case == "bomb":
        monkeypatch.setattr(Image, "MAX_IMAGE_PIXELS", 1)
    elif case == "total":
        monkeypatch.setattr(downloads, "MAX_TOTAL", len(data) - 1)
    writer, client = make_writer(tmp_path, data)
    service = JobService(writer.run, writer.storage_path)
    try:
        service.enqueue("pixiv-illust", "1", title="synthetic")
        failed = wait_terminal(service)
        assert failed.state == "error" and failed.result is None
        assert failed.error_code == code
        assert not tuple(writer.outputs.iterdir())
    finally:
        service.close()
        writer.close()

    calls = client.calls
    reopened = JobService(lambda *_: pytest.fail("failed job replayed"), writer.storage_path)
    try:
        assert reopened.snapshot()[0] == failed
        assert client.calls == calls
        assert b"synthetic-cookie" not in writer.storage_path.read_bytes()
        from nicegui import ui
        from pixivvault_nicegui.ui.job_views import QueueView
        with ui.column() as holder:
            view = QueueView(SimpleNamespace(jobs=reopened, artworks=()))
        try:
            text = view.rows[failed.job_id]["tooltip"].text
            assert phrase in text
            assert phrase in view.rows[failed.job_id]["result"].text
            assert all(value not in text for value in ("private", "token", "cookie", "S:/"))
        finally:
            view.close()
            holder.delete()
    finally:
        reopened.close()


def test_exact_size_boundaries_still_save_verified_image(tmp_path, monkeypatch):
    data = image_bytes()
    monkeypatch.setattr(downloads, "MAX_PAGE_BYTES", len(data))
    monkeypatch.setattr(downloads, "MAX_PIXELS", 4)
    monkeypatch.setattr(downloads, "MAX_TOTAL", len(data))
    writer, _ = make_writer(tmp_path, data)
    service = JobService(writer.run, writer.storage_path)
    try:
        service.enqueue("pixiv-illust", "1", title="synthetic")
        done = wait_terminal(service)
        assert done.state == "done" and done.error_code == ""
        receipt, _ = writer._receipt(done.result)
        assert receipt["files"][0]["bytes"] == len(data)
        assert receipt["files"][0]["width"] == receipt["files"][0]["height"] == 2
    finally:
        service.close()
        writer.close()
